// returns entry time t in [0,1] for the moving circle against the expanded AABB, or -1
function sweptEntry(px, py, x, y, r, brick) {
  const dx = x - px, dy = y - py;
  const minX = brick.x - r, maxX = brick.x + brick.w + r;
  const minY = brick.y - r, maxY = brick.y + brick.h + r;
  let tEnter = 0, tExit = 1;
  // X slab
  if (dx !== 0) {
    let t1 = (minX - px) / dx, t2 = (maxX - px) / dx;
    if (t1 > t2) [t1, t2] = [t2, t1];
    tEnter = Math.max(tEnter, t1);
    tExit = Math.min(tExit, t2);
  } else if (px < minX || px > maxX) {
    return -1;
  }
  // Y slab
  if (dy !== 0) {
    let t1 = (minY - py) / dy, t2 = (maxY - py) / dy;
    if (t1 > t2) [t1, t2] = [t2, t1];
    tEnter = Math.max(tEnter, t1);
    tExit = Math.min(tExit, t2);
  } else if (py < minY || py > maxY) {
    return -1;
  }
  if (tEnter <= tExit && tEnter >= 0 && tEnter <= 1) return Math.max(tEnter, 0);
  return -1;
}
```

