export function brickHit(ball, bricks) {
  let best = -1, bestT = Infinity;
  const px = ball.px ?? ball.x, py = ball.py ?? ball.y;
  for (let i=0;i<bricks.length;i++){
    if(!bricks[i].alive) continue;
    const t = sweptEntry(px, py, ball.x, ball.y, ball.r, bricks[i]);
    if (t >= 0 && t < bestT) { bestT = t; best = i; }
  }
  if (best === -1) return -1;
  const brick = bricks[best];
  // Move ball to entry contact position
  const ex = px + (ball.x - px) * bestT;
  const ey = py + (ball.y - py) * bestT;
  // Determine face by comparing penetration along each axis at contact
  // Use previous frame approach: compute penetration
  const left = ex + ball.r - brick.x;
  const right = brick.x + brick.w + ball.r - ex;
  const top = ey + ball.r - brick.y;
  const bottom = brick.y + brick.h + ball.r - ey;
  const pxOverlap = Math.min(left, right);
  const pyOverlap = Math.min(top, bottom);
  if (pxOverlap < pyOverlap) {
    ball.vx = -ball.vx;
    if (left < right) ball.x = brick.x - ball.r;
    else ball.x = brick.x + brick.w + ball.r;
    ball.y = ey;
  } else if (pyOverlap < pxOverlap) {
    ball.vy = -ball.vy;
    if (top < bottom) ball.y = brick.y - ball.r;
    else ball.y = brick.y + brick.h + ball.r;
    ball.x = ex;
  } else {
    // corner: flip both
    ball.vx = -ball.vx;
    ball.vy = -ball.vy;
    if (left < right) ball.x = brick.x - ball.r; else ball.x = brick.x + brick.w + ball.r;
    if (top < bottom) ball.y = brick.y - ball.r; else ball.y = brick.y + brick.h + ball.r;
  }
  return best;
}
```

