    const brick = bricks[i];
    if (!brick.alive) continue;
    const hit = sweepBall(px, py, ball.x, ball.y, ball.r, brick);
    if (hit && hit.t >= 0 && hit.t < bestT) {
      bestT = hit.t;
      bestIndex = i;
      bestFace = hit.face;
    }
  }

  if (bestIndex === -1) return -1;

  const brick = bricks[bestIndex];
  // move ball to entry position
  const ex = px + (ball.x - px) * bestT;
  const ey = py + (ball.y - py) * bestT;
  ball.x = ex; ball.y = ey;

  // reflect & push out
  const dx = ball.vx, dy = ball.vy;
  if (bestFace === 'x' || bestFace === 'both') {
    ball.vx = -dx;
    if (dx > 0) ball.x = brick.x - ball.r - 0.01;
    else ball.x = brick.x + brick.w + ball.r + 0.01;
